compiler_expanded_type:
H12PrincipalModel.principal_label_square (a b : Int) :
  have transform := fun v => (-v.snd, 0);
  transform (transform (a, b)) = (0, 0)

H12PrincipalSeven.based_third_carry :
  have w := H12PrincipalSeven.principal (0, 0, 1);
  (w.fst, w.snd.fst, w.snd.snd - 1) = (0, -15, -3)

H12DualFourier.dual_cubic (k : H12DualFourier.V) :
  have k1 := H12DualFourier.dual k;
  have k2 := H12DualFourier.dual k1;
  have k3 := H12DualFourier.dual k2;
  { x := k3.x - 6 * k2.x + 12 * k1.x - k.x, y := k3.y - 6 * k2.y + 12 * k1.y - k.y,
      z := k3.z - 6 * k2.z + 12 * k1.z - k.z } =
    { x := 0, y := 0, z := 0 }

H12UnitCoinvariants.residual_reconstruction (v : H12UnitCoinvariants.V) :
  H12UnitCoinvariants.delta (H12UnitCoinvariants.reconstruction v) =
    { x := v.x - H12UnitCoinvariants.ell v, y := v.y, z := v.z }

H12UnitCoinvariants.tripled_carry :
  H12UnitCoinvariants.delta H12UnitCoinvariants.e2 =
    { x := 3 * H12UnitCoinvariants.carry.x, y := 3 * H12UnitCoinvariants.carry.y, z := 3 * H12UnitCoinvariants.carry.z }

H12.CMThreefold.ordinary_fixed_identity (z : H12.ConjugationOrder.Eis) :
  H12.CMThreefold.sub (H12.CMThreefold.ordinary z) (H12.CMThreefold.companion (H12.CMThreefold.ordinary z)) =
    { c0 := H12.ConjugationOrder.escale 6 z, c1 := H12.ConjugationOrder.ez, c2 := H12.ConjugationOrder.ez }

H12.CMThreefold.seven_change_coordinates (z : H12.ConjugationOrder.Eis) :
  H12.CMThreefold.change (H12.CMThreefold.embed7 z) =
    { c0 := H12.ConjugationOrder.escale 56 z, c1 := H12.ConjugationOrder.ez, c2 := z }
